import { useEffect, useState } from "react"
import { io } from "socket.io-client"
import axios from "axios"

const socket = io("http://localhost:5001")

function App() {
  const [user, setUser] = useState("")
  const [other, setOther] = useState("")
  const [msg, setMsg] = useState("")
  const [list, setList] = useState([])
  const [room, setRoom] = useState("")

  const [emailInput, setEmailInput] = useState("")
  const [otherInput, setOtherInput] = useState("")

  const login = async (email) => {
    const res = await axios.post("http://localhost:5001/user/login", { email })
    setUser(res.data.name)
  }

  const joinRoom = async (user1, user2) => {
    const res = await axios.post("http://localhost:5001/chat", { user1, user2 })
    const r = [user1, user2].sort().join("_")
    setRoom(r)
    socket.emit("join_room", r)
  }

  const send = () => {
    socket.emit("send_message", { sender: user, receiver: other, text: msg, room })
    setMsg("")
  }

  useEffect(() => {
    socket.on("receive_message", data => setList(prev => [...prev, data]))
    return () => socket.off("receive_message")
  }, [])

  return (
    <div style={{ padding: "50px" }}>
      {!user && (
        <div>
          <input
            placeholder="email"
            value={emailInput}
            onChange={e => setEmailInput(e.target.value)}
          />
          <button onClick={() => login(emailInput)}>Login</button>
        </div>
      )}
      {user && !room && (
        <div>
          <input
            placeholder="chat with"
            value={otherInput}
            onChange={e => setOtherInput(e.target.value)}
          />
          <button onClick={() => { setOther(otherInput); joinRoom(user, otherInput) }}>
            Start Chat
          </button>
        </div>
      )}
      {room && (
        <>
          <h2>Chat with {other}</h2>
          <input placeholder="message" value={msg} onChange={e => setMsg(e.target.value)} />
          <button onClick={send}>Send</button>
          <div>
            {list.map((m, i) => (
              <p key={i}><b>{m.sender}:</b> {m.text}</p>
            ))}
          </div>
        </>
      )}
    </div>
  )
}

export default App
